// Tests for GifEncoderGpu (Images/Gif).
//
// Fixtures (TestData/GifEnc, generated by scripts/images/make_gif_encoder_fixtures.py): for every case the source
// frames, the file the encoder must produce BYTE FOR BYTE (written by an independent Python implementation of the
// documented algorithms: exact palette, median cut, nearest colour, ordered / Floyd-Steinberg dither, segmented LZW,
// GIF block layout), and the canvas every decoder must show. The generator also checks each expected file against
// Pillow's decode before it writes it.
//
// Oracles used here:
//   * the independent Python reference (byte-exact file comparison, which pins palette, indices, LZW bits, sub-blocks,
//     GCE / loop extension and table padding all at once);
//   * our own decoder, in both compositing modes (round trip);
//   * Pillow decoding OUR file (desktop lanes with SPAWNDEV_IMG_PYTHON set; otherwise Unsupported, never passed);
//   * a brute-force nearest-colour check against the palette parsed from the file's bytes;
//   * Pillow's median-cut PSNR recorded at generation time (the quantizer must be at least as good).
// What can fail: any byte of the output, the palette choice, the transparent index, dithering, segment boundaries,
// the 255 byte sub-blocking, GetMaxEncodedSize being too small, argument validation, the ArrayView1D overload writing
// outside its range.

using System.Text.Json;
using ILGPU;
using ILGPU.Runtime;
using SpawnDev.Codecs.Images;
using SpawnDev.Codecs.Images.Gif;
using SpawnDev.ILGPU;
using SpawnDev.UnitTesting;
using static SpawnDev.Codecs.Demo.Shared.UnitTests.TestHelpers;

namespace SpawnDev.Codecs.Demo.Shared.UnitTests;

public abstract partial class CodecsTestBase
{
    private const string GifEncPrefix = "SpawnDev.Codecs.Demo.Shared.TestData.GifEnc.";

    private sealed record GifEncCase(
        string Name, int Width, int Height, int Frames, GifEncodeOptions Options, byte[] Source, byte[] Expected, byte[] Canvas, JsonElement Meta);

    private static GifEncCase LoadGifEncCase(string name)
    {
        using var doc = JsonDocument.Parse(ReadEmbedded(GifEncPrefix + name + ".json"));
        var m = doc.RootElement.Clone();
        int[]? delays = m.GetProperty("delaysMs").ValueKind == JsonValueKind.Array
            ? m.GetProperty("delaysMs").EnumerateArray().Select(e => e.GetInt32()).ToArray() : null;
        FrameDispose[]? disposals = m.GetProperty("disposals").ValueKind == JsonValueKind.Array
            ? m.GetProperty("disposals").EnumerateArray().Select(e => e.GetInt32() switch { 2 => FrameDispose.Background, 3 => FrameDispose.Previous, _ => FrameDispose.None }).ToArray() : null;
        var options = new GifEncodeOptions
        {
            MaxColors = m.GetProperty("maxColors").GetInt32(),
            Dither = (GifDither)m.GetProperty("dither").GetInt32(),
            AlphaThreshold = m.GetProperty("alphaThreshold").GetInt32(),
            LoopCount = m.GetProperty("loop").GetInt32(),
            FrameDelayMs = m.GetProperty("frameDelayMs").GetInt32(),
            FrameDelaysMs = delays,
            FrameDisposals = disposals,
        };
        return new GifEncCase(name, m.GetProperty("width").GetInt32(), m.GetProperty("height").GetInt32(),
            m.GetProperty("frames").GetInt32(), options, ReadEmbedded(GifEncPrefix + name + ".src.rgba8"),
            ReadEmbedded(GifEncPrefix + name + ".expected.gif"), ReadEmbedded(GifEncPrefix + name + ".canvas.rgba8"), m);
    }

    private static string[] GifEncFixtureNames() => GifBmpFixtureNames(GifEncPrefix, ".expected.gif");

    private static async Task<byte[]> GifEncodeManagedAsync(GifEncoderGpu enc, GifEncCase c)
        => c.Frames == 1
            ? await enc.EncodeAsync(c.Source, c.Width, c.Height, c.Options)
            : await enc.EncodeAnimationAsync(c.Source, c.Width, c.Height, c.Frames, c.Options);

    private static string DescribeFirstByteDifference(byte[] expected, byte[] actual)
    {
        if (expected.Length != actual.Length)
        {
            int common = Math.Min(expected.Length, actual.Length);
            for (int i = 0; i < common; i++)
                if (expected[i] != actual[i]) return $"length {actual.Length} != expected {expected.Length}; first difference at byte {i} (got {actual[i]:X2}, expected {expected[i]:X2})";
            return $"length {actual.Length} != expected {expected.Length} (one is a prefix of the other)";
        }
        for (int i = 0; i < expected.Length; i++)
            if (expected[i] != actual[i]) return $"first difference at byte {i} of {expected.Length} (got {actual[i]:X2}, expected {expected[i]:X2})";
        return "identical";
    }

    [TestMethod]
    public async Task GifEncoderGpu_Fixtures_ProduceTheReferenceFileByteForByte_ManagedAndArrayView()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            var failures = new List<string>();
            int count = 0;
            foreach (var name in GifEncFixtureNames())
            {
                var c = LoadGifEncCase(name);
                try
                {
                    var managed = await GifEncodeManagedAsync(enc, c);
                    if (!managed.AsSpan().SequenceEqual(c.Expected))
                        failures.Add($"{name} [managed]: {DescribeFirstByteDifference(c.Expected, managed)}");

                    // ArrayView1D overload: input and output views longer than needed, output pre-filled with 0xAB.
                    int max = GifEncoderGpu.GetMaxEncodedSize(c.Width, c.Height, c.Frames, c.Options);
                    using var dIn = acc.Allocate1D<byte>(c.Source.Length + 13);
                    DeviceTransfer.Upload(dIn.View, c.Source);
                    using var dOut = acc.Allocate1D<byte>(max + 9);
                    var fill = new byte[dOut.Length];
                    System.Array.Fill(fill, (byte)0xAB);
                    DeviceTransfer.Upload(dOut.View, fill);
                    int length = await enc.EncodeAnimationAsync(dIn.View, c.Width, c.Height, c.Frames, dOut.View, c.Options);
                    var viaView = await DeviceTransfer.DownloadAsync(dOut.View, length);
                    if (!viaView.AsSpan().SequenceEqual(c.Expected))
                        failures.Add($"{name} [ArrayView1D]: {DescribeFirstByteDifference(c.Expected, viaView)}");
                    var tail = await dOut.View.SubView(length, dOut.Length - length).CopyToHostAsync();
                    // Nothing past the end of the file may change (the encoder writes only the file itself into the output view).
                    if (tail.Any(b => b != 0xAB))
                        failures.Add($"{name} [ArrayView1D]: wrote past the end of the file");
                    if (length > max) failures.Add($"{name}: length {length} exceeds GetMaxEncodedSize {max}");
                    count++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(count >= 35, $"only {count} fixtures ran");
            True(failures.Count == 0, $"{failures.Count} of {count + failures.Count} GIF encoder fixtures differ from the reference:\n" + string.Join("\n", failures));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifEncoderGpu_Fixtures_DecodeBackToTheCanvas_InBothDecoderModes()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            using var dec = new GifDecoderGpu(acc);
            var failures = new List<string>();
            int frameChecks = 0;
            foreach (var name in GifEncFixtureNames())
            {
                var c = LoadGifEncCase(name);
                try
                {
                    var file = await GifEncodeManagedAsync(enc, c);
                    int size = c.Width * c.Height * 4;
                    var info = await dec.ReadInfoAsync(file);
                    if (info.FrameCount != c.Frames || info.Width != c.Width || info.Height != c.Height)
                        failures.Add($"{name}: ReadInfo {info.Width}x{info.Height} x{info.FrameCount}");
                    foreach (var mode in new[] { GifCompositing.Pillow, GifCompositing.Web })
                    {
                        dec.Compositing = mode;
                        for (int k = 0; k < c.Frames; k++)
                        {
                            var img = await dec.DecodeFrameAsync(file, k);
                            var diff = ComparePixels(c.Canvas.AsSpan(k * size, size).ToArray(), img.Pixels, 4, c.Width);
                            if (diff != null) failures.Add($"{name} {mode} frame {k}: {diff}");
                            frameChecks++;
                        }
                    }
                    var frames = await dec.ReadFramesAsync(file);
                    int loop = await dec.ReadLoopCountAsync(file);
                    int expectedLoop = c.Frames > 1 ? c.Options.LoopCount : -1;
                    if (loop != expectedLoop) failures.Add($"{name}: loop count {loop} != {expectedLoop}");
                    // A graphic control extension (and so the delay) is written for animations and whenever something is transparent.
                    bool anyTransparent = false;
                    for (int p = 3; p < c.Canvas.Length; p += 4) if (c.Canvas[p] == 0) { anyTransparent = true; break; }
                    for (int k = 0; k < frames.Length; k++)
                    {
                        int ms = c.Options.FrameDelaysMs != null ? c.Options.FrameDelaysMs[k] : c.Options.FrameDelayMs;
                        int expectedMs = c.Frames > 1 || anyTransparent ? (ms + 5) / 10 * 10 : 0;
                        if (frames[k].DurationMs != expectedMs) failures.Add($"{name}[{k}]: duration {frames[k].DurationMs} != {expectedMs}");
                        if (frames[k].X != 0 || frames[k].Y != 0 || frames[k].Width != c.Width || frames[k].Height != c.Height)
                            failures.Add($"{name}[{k}]: frame rectangle {frames[k].X},{frames[k].Y} {frames[k].Width}x{frames[k].Height}");
                    }
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            dec.Compositing = GifCompositing.Pillow;
            True(frameChecks >= 250, $"only {frameChecks} frames checked");
            True(failures.Count == 0, $"{failures.Count} round-trip failures:\n" + string.Join("\n", failures.Take(40)));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifEncoderGpu_PillowDecodesOurFiles_ToTheSamePixels()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            var failures = new List<string>();
            int count = 0;
            foreach (var name in GifEncFixtureNames())
            {
                var c = LoadGifEncCase(name);
                var file = await GifEncodeManagedAsync(enc, c);
                var pillow = PillowOracle.Decode(file, ".gif");      // Unsupported (not passed) without SPAWNDEV_IMG_PYTHON
                int size = c.Width * c.Height * 4;
                if (pillow.Format != "GIF" || pillow.Width != c.Width || pillow.Height != c.Height || pillow.Frames != c.Frames)
                {
                    failures.Add($"{name}: Pillow sees {pillow.Format} {pillow.Width}x{pillow.Height} x{pillow.Frames}");
                    continue;
                }
                for (int k = 0; k < c.Frames; k++)
                {
                    var diff = ComparePixels(c.Canvas.AsSpan(k * size, size).ToArray(), pillow.FramesRgba[k], 4, c.Width);
                    if (diff != null) failures.Add($"{name} frame {k}: {diff}");
                    int ms = c.Options.FrameDelaysMs != null ? c.Options.FrameDelaysMs[k] : c.Options.FrameDelayMs;
                    int expectedMs = c.Frames > 1 ? (ms + 5) / 10 * 10 : 0;
                    int got = pillow.Durations[k] ?? 0;
                    if (c.Frames > 1 && got != expectedMs) failures.Add($"{name}[{k}]: Pillow duration {got} != {expectedMs}");
                }
                int? expectedLoop = c.Frames > 1 && c.Options.LoopCount >= 0 ? c.Options.LoopCount : null;
                if (pillow.Loop != expectedLoop) failures.Add($"{name}: Pillow loop {pillow.Loop?.ToString() ?? "none"} != {expectedLoop?.ToString() ?? "none"}");
                count++;
            }
            True(failures.Count == 0, $"{failures.Count} Pillow disagreements ({count} fixtures ok):\n" + string.Join("\n", failures.Take(40)));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    /// <summary>Squared RGB distance.</summary>
    private static int GifDist2(int r0, int g0, int b0, int r1, int g1, int b1) => (r0 - r1) * (r0 - r1) + (g0 - g1) * (g0 - g1) + (b0 - b1) * (b0 - b1);

    [TestMethod]
    public async Task GifEncoderGpu_QuantizedPictures_MapEveryPixelToANearestPaletteColour_AndBeatPillowMedianCut()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            using var dec = new GifDecoderGpu(acc);
            var failures = new List<string>();
            int checkedCases = 0;
            foreach (var name in GifEncFixtureNames())
            {
                var c = LoadGifEncCase(name);
                if (c.Frames != 1 || c.Options.Dither != GifDither.None) continue;
                var file = await GifEncodeManagedAsync(enc, c);
                // palette straight from the file bytes: a global table (single pictures always have one)
                if ((file[10] & 0x80) == 0) { failures.Add($"{name}: no global colour table"); continue; }
                int tableSize = 2 << (file[10] & 7);
                var palette = new List<(int R, int G, int B)>();
                for (int i = 0; i < tableSize; i++) palette.Add((file[13 + i * 3], file[14 + i * 3], file[15 + i * 3]));
                // The table is padded with black up to a power of two and (with transparency) ends with the black transparent entry,
                // and a sorted palette keeps a real black entry first: strip the trailing black entries (entry 0 stays).
                while (palette.Count > 1 && palette[^1] == (0, 0, 0)) palette.RemoveAt(palette.Count - 1);
                var img = (await dec.DecodeAsync(file)).Pixels;
                int px = c.Width * c.Height;
                double sq = 0;
                long opaque = 0;
                bool quantized = false;
                for (int p = 0; p < px; p++)
                {
                    if (c.Source[p * 4 + 3] < c.Options.AlphaThreshold)
                    {
                        if (img[p * 4 + 3] != 0) failures.Add($"{name}: pixel {p} should be transparent");
                        continue;
                    }
                    int r = c.Source[p * 4], g = c.Source[p * 4 + 1], b = c.Source[p * 4 + 2];
                    int pr = img[p * 4], pg = img[p * 4 + 1], pb = img[p * 4 + 2];
                    int best = int.MaxValue;
                    foreach (var e in palette) best = Math.Min(best, GifDist2(r, g, b, e.R, e.G, e.B));
                    int d = GifDist2(r, g, b, pr, pg, pb);
                    if (d != best) { failures.Add($"{name}: pixel {p} maps to a colour at distance^2 {d}, a palette colour is at {best}"); break; }
                    if (d != 0) quantized = true;
                    sq += d;
                    opaque++;
                }
                if (!quantized) continue;           // exact palette: lossless, nothing to compare
                double psnr = 10 * Math.Log10(255.0 * 255.0 * 3 * opaque / Math.Max(1, sq));
                // PSNR over the three colour channels of the opaque pixels. Pillow's value (median cut, no dither) was recorded by the generator.
                if (c.Meta.TryGetProperty("pillowMedianCutPsnr", out var pp) && pp.ValueKind == JsonValueKind.Number)
                {
                    double pillowPsnr = pp.GetDouble();
                    // From 16 colours up the quantizer must be at least as good as Pillow's median cut; with a handful of colours
                    // (2, 3) Pillow's splitting heuristic is better by up to ~2.5 dB on this picture, and 3 dB is the allowed gap.
                    int budget = c.Options.MaxColors;
                    double allowed = budget >= 16 ? 0.0 : 3.0;
                    if (psnr < pillowPsnr - allowed) failures.Add($"{name}: PSNR {psnr:F2} dB is below Pillow's median cut {pillowPsnr:F2} dB (allowed gap {allowed} dB)");
                    Console.WriteLine($"GifEncoderGpu quantizer {name}: PSNR {psnr:F2} dB (Pillow median cut {pillowPsnr:F2} dB, FASTOCTREE {c.Meta.GetProperty("pillowOctreePsnr").GetDouble():F2} dB)");
                }
                checkedCases++;
            }
            True(failures.Count == 0, string.Join("\n", failures));
            True(checkedCases >= 6, $"only {checkedCases} quantized cases checked");
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    // ------------------------------------------------------------------
    // Round trips on inputs the fixtures do not cover
    // ------------------------------------------------------------------

    /// <summary>The canvas a lossless (exact palette) encode must show: transparent pixels (0,0,0,0), others opaque with the same RGB.</summary>
    private static byte[] ExpectedExactCanvas(byte[] rgba, int threshold)
    {
        var e = new byte[rgba.Length];
        for (int p = 0; p < rgba.Length; p += 4)
        {
            if (rgba[p + 3] < threshold) continue;
            e[p] = rgba[p]; e[p + 1] = rgba[p + 1]; e[p + 2] = rgba[p + 2]; e[p + 3] = 255;
        }
        return e;
    }

    [TestMethod]
    public async Task GifEncoderGpu_RandomExactInputs_RoundTripLosslessly_AcrossSizesFramesAndSegments()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            using var dec = new GifDecoderGpu(acc);
            var failures = new List<string>();
            var rng = new Random(20261022);
            int cases = 0, losslessSkipped = 0;
            // sizes around the 32768 pixel segment boundary, 1-wide / 1-high, and ordinary
            var sizes = new List<(int W, int H)> { (1, 1), (2, 1), (1, 2), (7, 5), (181, 181), (182, 180), (183, 179), (32768, 1), (1, 32769), (200, 164), (257, 129), (700, 150), (301, 301), (131, 500) };
            for (int i = 0; i < 12; i++) sizes.Add((1 + rng.Next(120), 1 + rng.Next(90)));
            foreach (var (w, h) in sizes)
            {
                int frames = (long)w * h > 40000 ? 1 : 1 + rng.Next(5);
                int colours = new[] { 1, 2, 3, 17, 100, 255, 256 }[rng.Next(7)];
                bool alpha = rng.Next(2) == 0;
                var all = new byte[w * h * 4 * frames];
                int threshold = new[] { 128, 1, 200 }[rng.Next(3)];
                for (int f = 0; f < frames; f++)
                {
                    var fr = MakeRgba(w, h, 7000 + f * 13 + w + h, colours, false);
                    if (alpha)
                        for (int p = 0; p < w * h; p++)
                            if (rng.Next(5) == 0) fr[p * 4 + 3] = (byte)rng.Next(256);
                    fr.CopyTo(all, f * w * h * 4);
                }
                // Exact (lossless) when the distinct opaque colours of all frames, plus the transparent index, fit 256 entries.
                var distinct = new HashSet<int>();
                bool anyTransparent = false;
                for (int p = 0; p < all.Length; p += 4)
                {
                    if (all[p + 3] < threshold) anyTransparent = true;
                    else distinct.Add((all[p] << 16) | (all[p + 1] << 8) | all[p + 2]);
                }
                var options = new GifEncodeOptions { AlphaThreshold = threshold, MaxColors = 256, FrameDelayMs = 30 };
                try
                {
                    var file = frames == 1 ? await enc.EncodeAsync(all, w, h, options) : await enc.EncodeAnimationAsync(all, w, h, frames, options);
                    int size = w * h * 4;
                    // exact when colours (+ transparent index) fit; MakeRgba never exceeds 256 colours per frame, but the union of frames can
                    bool lossless = distinct.Count + (anyTransparent ? 1 : 0) <= 256;
                    if (!lossless) { cases++; losslessSkipped++; continue; }
                    for (int k = 0; k < frames; k++)
                    {
                        var img = await dec.DecodeFrameAsync(file, k);
                        var expected = ExpectedExactCanvas(all.AsSpan(k * size, size).ToArray(), threshold);
                        var diff = ComparePixels(expected, img.Pixels, 4, w);
                        if (diff != null) failures.Add($"{w}x{h} x{frames} colours={colours} alpha={alpha} thr={threshold} frame {k}: {diff}");
                    }
                    int max = GifEncoderGpu.GetMaxEncodedSize(w, h, frames, options);
                    if (file.Length > max) failures.Add($"{w}x{h}: {file.Length} bytes exceeds GetMaxEncodedSize {max}");
                    cases++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{w}x{h} x{frames}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(cases >= 20, $"only {cases} cases ran");
            True(losslessSkipped <= cases / 2, $"{losslessSkipped} of {cases} cases were not lossless: the test would prove too little");
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod(Timeout = 600000)]
    public async Task GifEncoderGpu_WorstCaseNoise_StaysInsideGetMaxEncodedSize_AndDecodesExactly()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            using var dec = new GifDecoderGpu(acc);
            var failures = new List<string>();
            // 256 random colours: the LZW table fills over and over (the dictionary never helps).
            foreach (var (w, h) in new[] { (512, 512), (1000, 3), (3, 1000) })
            {
                var rgba = MakeRgba(w, h, 99 + w, 256, false);
                var file = await enc.EncodeAsync(rgba, w, h);
                int max = GifEncoderGpu.GetMaxEncodedSize(w, h);
                if (file.Length > max) failures.Add($"{w}x{h}: {file.Length} > {max}");
                var img = await dec.DecodeAsync(file);
                var diff = ComparePixels(rgba, img.Pixels, 4, w);
                if (diff != null) failures.Add($"{w}x{h}: {diff}");
            }
            // full-colour noise: quantized (nothing exact), floyd-steinberg and ordered on a picture of several segments
            var noise = MakeRgba(300, 200, 5, 0, false);
            foreach (var dither in new[] { GifDither.None, GifDither.Ordered, GifDither.FloydSteinberg })
            {
                var file = await enc.EncodeAsync(noise, 300, 200, new GifEncodeOptions { Dither = dither });
                if (file.Length > GifEncoderGpu.GetMaxEncodedSize(300, 200)) failures.Add($"noise {dither}: {file.Length} exceeds the bound");
                var img = await dec.DecodeAsync(file);
                if (img.Info.Width != 300 || img.Info.Height != 200) failures.Add($"noise {dither}: decoded {img.Info.Width}x{img.Info.Height}");
                for (int p = 3; p < img.Pixels.Length; p += 4) if (img.Pixels[p] != 255) { failures.Add($"noise {dither}: alpha {img.Pixels[p]} at {p / 4}"); break; }
            }
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifEncoderGpu_ArgumentValidation_RejectsBadInputsWithTheRightExceptions()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            var px = new byte[4 * 4 * 4];
            int caught = 0, expected = 0;
            async Task Expect<T>(Func<Task> action, string what) where T : Exception
            {
                expected++;
                try { await action(); }
                catch (T) { caught++; return; }
                catch (Exception ex) { throw new Exception($"{what}: expected {typeof(T).Name}, got {ex.GetType().Name}: {ex.Message}"); }
                throw new Exception($"{what}: no exception, expected {typeof(T).Name}");
            }
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAsync(px, 0, 4), "width 0");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAsync(px, 4, 0), "height 0");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAsync(px, 65536, 1), "width 65536");
            await Expect<ArgumentException>(() => enc.EncodeAsync(new byte[10], 4, 4), "input too short");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAsync(px, 4, 4, new GifEncodeOptions { MaxColors = 1 }), "MaxColors 1");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAsync(px, 4, 4, new GifEncodeOptions { MaxColors = 257 }), "MaxColors 257");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAsync(px, 4, 4, new GifEncodeOptions { AlphaThreshold = -1 }), "AlphaThreshold -1");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAsync(px, 4, 4, new GifEncodeOptions { AlphaThreshold = 257 }), "AlphaThreshold 257");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAsync(px, 4, 4, new GifEncodeOptions { LoopCount = -2 }), "LoopCount -2");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAsync(px, 4, 4, new GifEncodeOptions { Dither = (GifDither)9 }), "dither 9");
            await Expect<ArgumentException>(() => enc.EncodeAnimationAsync(new byte[4 * 4 * 4 * 2], 4, 4, 2, new GifEncodeOptions { FrameDelaysMs = new[] { 10 } }), "1 delay for 2 frames");
            await Expect<ArgumentException>(() => enc.EncodeAnimationAsync(new byte[4 * 4 * 4 * 2], 4, 4, 2, new GifEncodeOptions { FrameDisposals = new[] { FrameDispose.None } }), "1 disposal for 2 frames");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAnimationAsync(px, 4, 4, 0), "0 frames");
            await Expect<ArgumentOutOfRangeException>(() => enc.EncodeAnimationAsync(px, 4, 4, GifMeta.MaxFrames + 1), "too many frames");
            await Expect<ArgumentException>(() => enc.EncodeAnimationAsync(px, 4, 4, 2), "2 frames of input, 1 supplied");
            // output view too small
            using var small = acc.Allocate1D<byte>(100);
            using var input = acc.Allocate1D<byte>(px.Length);
            expected++;
            try { await enc.EncodeAsync(input.View, 4, 4, small.View); } catch (ArgumentException) { caught++; }
            Equal(expected, caught, "every bad call must throw");
            // and the encoder is still usable afterwards
            var ok = await enc.EncodeAsync(px, 4, 4);
            True(ok.Length > 20 && ok[0] == (byte)'G', "usable after rejected calls");
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifEncoderGpu_InstanceIsReusable_AcrossSizesFramesAndModes()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            var failures = new List<string>();
            // big, tiny, animation, big again, with different options: grow-only buffers and the shared builders must not leak state
            foreach (var name in new[] { "quant_photo_320x180_256_none_multi_segment", "exact_1x1", "anim_quant_3x_floyd", "exact_multi_segment_noise_400x300",
                                         "exact_two_colours_5x3", "quant_photo_160x90_max16_d2", "anim_exact_70_frames", "exact_1x1", "anim_quant_3x_floyd" })
            {
                var c = LoadGifEncCase(name);
                var file = await GifEncodeManagedAsync(enc, c);
                if (!file.AsSpan().SequenceEqual(c.Expected)) failures.Add($"{name}: {DescribeFirstByteDifference(c.Expected, file)}");
            }
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    private static byte[] MakeLargeRunsPicture(int w, int h)
    {
        var rgba = MakeRgba(w, h, 31337, 200, false);
        // duplicate every other row so the dictionary matters too
        for (int y = 0; y + 1 < h; y += 2)
            for (int x = 0; x < w; x++)
                System.Array.Copy(rgba, ((y * w) + x) * 4, rgba, (((y + 1) * w) + x) * 4, 4);
        return rgba;
    }

    [TestMethod]
    public async Task GifEncoderGpu_LargePicture_ManySegments_RoundTripsThroughOurDecoder()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            using var dec = new GifDecoderGpu(acc);
            const int w = 1024, h = 768;                      // 786432 pixels = 24 segments
            var rgba = MakeLargeRunsPicture(w, h);
            var file = await enc.EncodeAsync(rgba, w, h);
            var img = await dec.DecodeAsync(file);
            var diff = ComparePixels(rgba, img.Pixels, 4, w);
            True(diff == null, "round trip: " + diff);
            True(file.Length <= GifEncoderGpu.GetMaxEncodedSize(w, h), "bound");
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifEncoderGpu_LargePicture_PillowAgrees()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var enc = new GifEncoderGpu(acc);
            const int w = 1024, h = 768;
            var rgba = MakeLargeRunsPicture(w, h);
            var file = await enc.EncodeAsync(rgba, w, h);
            var pillow = PillowOracle.Decode(file, ".gif");
            var pdiff = ComparePixels(rgba, pillow.FramesRgba[0], 4, w);
            True(pdiff == null, "Pillow: " + pdiff);
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }
